local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters



-- ========================================================




-- ========================================================

function PipelineVCamTrigger:__init()
    self.controller = nil
    self._controller = nil -- PipelineVCamController
end


function PipelineVCamTrigger:__delete()
end


function PipelineVCamTrigger:Awake()
    KTool.SetActive(self.controller.gameObject, true)


    self.params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.params )
    self.direction = LuaParametersReader.Read( self.params, "direction", LuaParametersType.Int ) -- 1,-1

    self._collider = KTool.GetComponent(self.controller.gameObject, typeof(Collider))
    assert( self._collider )


    -- ==============================
    -- 绑定 OnTriggerEnter() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end

        behaviourAction.OnTriggerExitAction = function(behaviourAction,other_)
            self:OnTriggerExit(other_)
        end
    end
end


function PipelineVCamTrigger:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function PipelineVCamTrigger:SetController( controller_ )
    self._controller = controller_
end



---@return void
---@param other_ UnityEngine.Collider
function PipelineVCamTrigger:OnTriggerEnter(other_)
    self._controller:Enable( other_.gameObject, self.direction )
end


---@return void
---@param other_ UnityEngine.Collider
function PipelineVCamTrigger:OnTriggerExit(other_)

    -- 之所以得到的这个点 躺在地板上, 是因为猫的 capsuleCollider 的 pos 就在底部, 它的 collider 存在纵向 offset... 

    local closedPos = self._collider:ClosestPoint( other_.transform.position )

    print( "-- othPos    = " .. other_.transform.position:ToString() )
    print( "-- closedPos = " .. closedPos:ToString() )


    self._controller:Disable( self, other_.gameObject, closedPos )
end



function PipelineVCamTrigger:CalculateClosedPoint( srcPos_ )
    return self._collider:ClosestPoint( srcPos_ )
end





return PipelineVCamTrigger

